import{_ as e,o as d,c as a,ae as o}from"./chunks/framework.D3uQw3tB.js";const u=JSON.parse('{"title":"Views","description":"","frontmatter":{},"headers":[],"relativePath":"mcp/views.md","filePath":"mcp/views.md"}'),s={name:"mcp/views.md"};function r(c,t,n,i,l,p){return d(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="views" tabindex="-1">Views <a class="header-anchor" href="#views" aria-label="Permalink to &quot;Views&quot;">​</a></h1><p>Tools for rendering deck views in different formats. Each view is a separate tool.</p><h2 id="deck-list" tabindex="-1"><code>deck_list</code> <a class="header-anchor" href="#deck-list" aria-label="Permalink to &quot;`deck_list`&quot;">​</a></h2><p>Primary deck-analysis view. Returns the full card list as markdown with Oracle text. Supports grouping, sorting, and filtering.</p><table tabindex="0"><thead><tr><th>Param</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>deck_id</code></td><td>string</td><td>yes</td><td>Deck UUID</td></tr><tr><td><code>detail</code></td><td>string</td><td>no</td><td><code>summary</code>, <code>compact</code> (default), or <code>full</code></td></tr><tr><td><code>sort_by</code></td><td>string</td><td>no</td><td><code>name</code> or <code>set</code></td></tr><tr><td><code>group_by</code></td><td>string</td><td>no</td><td><code>none</code> (default), <code>role</code>, or <code>type</code></td></tr><tr><td><code>filters</code></td><td>object[]</td><td>no</td><td>Array of filter objects</td></tr></tbody></table><p>Each filter object:</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>type</code></td><td>string</td><td><code>cmc</code>, <code>color</code>, <code>card-type</code>, <code>role</code>, or <code>ownership</code></td></tr><tr><td><code>mode</code></td><td>string</td><td><code>include</code> or <code>exclude</code></td></tr><tr><td><code>values</code></td><td>any[]</td><td>Values to match (ownership values: <code>unknown</code>, <code>owned</code>, <code>need_to_buy</code>)</td></tr></tbody></table><p><strong>Response:</strong> Markdown-formatted string of the rendered deck view.</p><h3 id="detail-levels" tabindex="-1">Detail levels <a class="header-anchor" href="#detail-levels" aria-label="Permalink to &quot;Detail levels&quot;">​</a></h3><p>The <code>detail</code> parameter controls how much card information is shown (requires Scryfall cache):</p><p><strong><code>summary</code></strong> — One line per card with mana cost and primary type:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>- 1x Sol Ring • {1} [Artifact] (Ramp) [NEED TO BUY]</span></span></code></pre></div><p><strong><code>compact</code></strong> (default) — Mana cost, full type line, P/T, and oracle text:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>- 1x Sol Ring • {1} Artifact (Ramp)</span></span>\n<span class="line"><span>  {T}: Add {C}{C}.</span></span></code></pre></div><p><strong><code>full</code></strong> — Everything: set, rarity, full type line, P/T, and oracle text:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>- 1x Swords to Plowshares • STA#10 • mythic • {W} Instant (Removal) [NEED TO BUY]</span></span>\n<span class="line"><span>  Exile target creature. Its controller gains life equal to its power.</span></span></code></pre></div><p>When no cached Scryfall data is available, all levels fall back to card name only.</p><h2 id="deck-curve" tabindex="-1"><code>deck_curve</code> <a class="header-anchor" href="#deck-curve" aria-label="Permalink to &quot;`deck_curve`&quot;">​</a></h2><p>Mana curve analysis for a deck: CMC distribution, color pip counts, and type breakdown.</p><table tabindex="0"><thead><tr><th>Param</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>deck_id</code></td><td>string</td><td>yes</td><td>Deck UUID</td></tr><tr><td><code>filters</code></td><td>object[]</td><td>no</td><td>Card filters (same schema as <code>deck_list</code>)</td></tr></tbody></table><p><strong>Response:</strong> Markdown string with mana curve analysis.</p><h2 id="deck-notes" tabindex="-1"><code>deck_notes</code> <a class="header-anchor" href="#deck-notes" aria-label="Permalink to &quot;`deck_notes`&quot;">​</a></h2><p>Deck strategy notes: combos, synergies, themes, and game-plan commentary.</p><table tabindex="0"><thead><tr><th>Param</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>deck_id</code></td><td>string</td><td>yes</td><td>Deck UUID</td></tr></tbody></table><p><strong>Response:</strong> Markdown string with strategy notes and card references.</p><h2 id="deck-pull-list" tabindex="-1"><code>deck_pull_list</code> <a class="header-anchor" href="#deck-pull-list" aria-label="Permalink to &quot;`deck_pull_list`&quot;">​</a></h2><p>Cards grouped by set for physical collection pulling, with pulled-status tracking.</p><table tabindex="0"><thead><tr><th>Param</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>deck_id</code></td><td>string</td><td>yes</td><td>Deck UUID</td></tr></tbody></table><p><strong>Response:</strong> Markdown string with cards organized by set.</p>',29)])])}const b=e(s,[["render",r]]);export{u as __pageData,b as default};
